// Calculate the current week's date range (Monday 00:00 to now)
// Runs every Friday at 5pm - captures Mon-Fri activity
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Sun, 1=Mon, ..., 5=Fri, 6=Sat
const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1; // days since Monday
const monday = new Date(now);
monday.setDate(now.getDate() - diff);
monday.setHours(0, 0, 0, 0);

const since = monday.toISOString();
const until = now.toISOString();
const weekStart = monday.toISOString().split('T')[0];
const weekEnd = now.toISOString().split('T')[0];

// ═══════════════════════════════════════════
// CONFIGURATION - Edit these values
// ═══════════════════════════════════════════
const config = {
  owner: 'claude-builders-bounty',
  repo: 'claude-builders-bounty',
  githubToken: process.env.GITHUB_TOKEN || 'YOUR_GITHUB_PERSONAL_ACCESS_TOKEN',
  claudeApiKey: process.env.CLAUDE_API_KEY || 'YOUR_CLAUDE_API_KEY',
  githubApiBase: 'https://api.github.com'
};

return [{
  json: {
    ...config,
    since,
    until,
    weekStart,
    weekEnd,
    weekLabel: `${weekStart} to ${weekEnd}`,
    generatedAt: now.toISOString()
  }
}];

// Process and format commit data from GitHub API response
const commitsResponse = $input.first().json;

let commits = [];
if (Array.isArray(commitsResponse)) {
  commits = commitsResponse;
} else if (commitsResponse.body && Array.isArray(commitsResponse.body)) {
  commits = commitsResponse.body;
}

const formatted = commits.slice(0, 30).map(c => ({
  sha: c.sha ? c.sha.substring(0, 7) : 'unknown',
  message: c.commit ? (c.commit.message || '').split('\n')[0].trim() : (c.message || 'N/A'),
  author: (c.commit && c.commit.author) ? c.commit.author.name : (c.author ? c.author.login : 'unknown'),
  date: (c.commit && c.commit.author) ? c.commit.author.date : (c.created_at || 'unknown'),
  url: c.html_url || `https://github.com/${$('Calculate Week Range').first().json.owner}/${$('Calculate Week Range').first().json.repo}/commit/${c.sha}`
}));

return [{
  json: {
    commits: formatted,
    commitsCount: commits.length
  }
}];

// Process and format closed issues, filtering out PRs
const issuesResponse = $input.first().json;

let issues = [];
if (Array.isArray(issuesResponse)) {
  issues = issuesResponse;
} else if (issuesResponse.body && Array.isArray(issuesResponse.body)) {
  issues = issuesResponse.body;
}

// Filter out pull requests (GitHub issues API returns PRs too)
const pureIssues = issues.filter(i => !i.pull_request);

const formatted = pureIssues.slice(0, 30).map(i => ({
  number: i.number,
  title: i.title,
  user: i.user ? i.user.login : 'unknown',
  state: i.state,
  closedAt: i.closed_at || 'unknown',
  labels: i.labels ? i.labels.map(l => l.name) : [],
  url: i.html_url || ''
}));

return [{
  json: {
    issues: formatted,
    issuesCount: pureIssues.length
  }
}];

// Aggregate all collected data and build the Claude API prompt
const config = $('Calculate Week Range').first().json;
const commitsData = $('Process Commits').first().json;
const issuesData = $('Process Issues').first().json;
const prsResponse = $input.first().json;

// Parse PRs
let prs = [];
if (Array.isArray(prsResponse)) {
  prs = prsResponse;
} else if (prsResponse.body && Array.isArray(prsResponse.body)) {
  prs = prsResponse.body;
}

// Filter to PRs from this week using since date
const weekSince = new Date(config.since);
const recentPRs = prs.filter(p => {
  const closedDate = new Date(p.closed_at || p.updated_at || 0);
  return closedDate >= weekSince;
});

const formattedPRs = recentPRs.slice(0, 20).map(p => ({
  number: p.number,
  title: p.title,
  user: p.user ? p.user.login : 'unknown',
  state: p.state,
  merged: p.merged_at ? true : false,
  closedAt: p.closed_at || 'unknown',
  mergedAt: p.merged_at || null,
  url: p.html_url || ''
}));

// Build commits list for prompt
const commitsList = commitsData.commits && commitsData.commits.length > 0
  ? commitsData.commits.map((c, i) => `${i + 1}. [${c.sha}] ${c.message} - ${c.author} (${c.date})`).join('\n')
  : 'No commits this week.';

// Build issues list for prompt
const issuesList = issuesData.issues && issuesData.issues.length > 0
  ? issuesData.issues.map((i, idx) => `${idx + 1}. #${i.number} ${i.title} - closed by ${i.user}${i.labels && i.labels.length ? ' [' + i.labels.join(', ') + ']' : ''}`).join('\n')
  : 'No issues closed this week.';

// Build PRs list for prompt
const prsList = formattedPRs.length > 0
  ? formattedPRs.map((p, idx) => `${idx + 1}. #${p.number} ${p.title} - by ${p.user}${p.merged ? ' ✅ merged' : ' ❌ closed'} (${p.closedAt})`).join('\n')
  : 'No PRs closed this week.';

// Collect all unique contributors
const allContributors = new Set();
commitsData.commits?.forEach(c => allContributors.add(c.author));
issuesData.issues?.forEach(i => allContributors.add(i.user));
formattedPRs.forEach(p => allContributors.add(p.user));
const contributorsList = [...allContributors].filter(Boolean).join(', ');

// Build the Claude prompt
const prompt = `You are a helpful developer relations assistant. Generate a weekly development summary for the GitHub repository "${config.owner}/${config.repo}".

## Repository: ${config.owner}/${config.repo}
## Week: ${config.weekLabel}
## All Contributors This Week: ${contributorsList || 'None'}

---

### Commits This Week (${commitsData.commitsCount} total):
${commitsList}

### Closed Issues (${issuesData.issuesCount} total):
${issuesList}

### Merged/Closed Pull Requests (${formattedPRs.length} total):
${prsList}

---

Please generate a weekly summary with these sections:

1. **🏆 Highlight of the Week** - The single most significant change, achievement, or milestone. Be specific.

2. **🔑 Key Changes** - Summarize the most important commits and their impact. Group related changes together. Focus on what changed and why it matters.

3. **🌟 Contributor Shoutouts** - Recognize contributors by name. Be specific about what each person contributed. If someone had multiple contributions, highlight their best work. Use their GitHub usernames with @ mentions.

4. **📋 Upcoming Priorities** - Based on the activity patterns, suggest 2-4 logical next priorities for the coming week. Be actionable and specific.

5. **📊 Weekly Stats** - Quick stats block:
   - Commits: ${commitsData.commitsCount}
   - Issues Closed: ${issuesData.issuesCount}
   - PRs Merged/Closed: ${formattedPRs.length}
   - Active Contributors: ${allContributors.size}

Format the response in clean, engaging Markdown suitable for posting in a team chat or discussion thread. Keep it concise but informative — aim for 300-500 words total. Use emoji sparingly and tastefully.

Start your response directly with "# Weekly Dev Summary" as the title.`;

return [{
  json: {
    prompt,
    model: 'claude-sonnet-4-20250514',
    maxTokens: 2048,
    weekLabel: config.weekLabel,
    summaryData: {
      commitsCount: commitsData.commitsCount,
      issuesCount: issuesData.issuesCount,
      prsCount: formattedPRs.length,
      contributorsCount: allContributors.size
    }
  }
}];

// Parse Claude API response and format the final output
const claudeResponse = $input.first().json;
const config = $('Calculate Week Range').first().json;
const aggregateData = $('Aggregate All Data').first().json;

let summaryContent = '';

// Parse Claude's Messages API response format
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  // Standard Anthropic Messages API response
  summaryContent = claudeResponse.content
    .map(c => c.text || '')
    .join('\n');
} else if (claudeResponse.choices && Array.isArray(claudeResponse.choices)) {
  // OpenAI-compatible format
  summaryContent = claudeResponse.choices[0]?.message?.content || '';
} else if (claudeResponse.completion) {
  // Legacy completions format
  summaryContent = claudeResponse.completion;
} else if (typeof claudeResponse === 'string') {
  summaryContent = claudeResponse;
} else {
  // Fallback: stringify the whole response
  summaryContent = JSON.stringify(claudeResponse, null, 2);
}

// Build the final structured output
const finalOutput = {
  repo: `${config.owner}/${config.repo}`,
  weekLabel: config.weekLabel,
  generatedAt: new Date().toISOString(),
  stats: aggregateData.summaryData,
  summary: summaryContent,
  usage: claudeResponse.usage || null,
  model: claudeResponse.model || 'claude-sonnet-4-20250514'
};

return [{
  json: finalOutput
}];
